function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 120, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 100);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 70);
  ctx.lineTo(W/2 - 30, H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 70);
  ctx.lineTo(W/2 + 30, H/2 - 40);
  ctx.stroke();

  // applying wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying Wisdom', W/2, H/2 + 70 + 20 * Math.sin(t));

  // lesson life
  ctx.font = '18px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson: ' + Math.floor(1 + 235 * Math.abs(Math.sin(t))), 20, 20);

  ctx.restore();
}
